/bin/bash -lc 'KEY=$(cat "$GALAXY_API_KEY_FILE"); curl -sS -H "x-api-key: $KEY" "$GALAXY_URL/api/tools/toolshed.g2.bx.psu.edu/repos/devteam/bowtie2/bowtie2/2.5.5+galaxy0/build?history_id=bbd44e69cb8906b54c490a68f18797a4" -o [REDACTED LOCAL PATH] python3 - <<'"'PY'
import json
p='[REDACTED LOCAL PATH]'
d=json.load(open(p))
s=json.dumps(d)
for term in ['hg38','hg19','GRCh38','Human (Homo sapiens)']:
 i=s.find(term)
 print(term, i)
 if i"'!=-1:
  print(s[i-200:i+300])
# print conditional structures for library and reference
for inp in d.get('"'inputs',[]):
 print('\\nTOP', inp.get('name'), inp.get('type'), 'value=',inp.get('value'))
 if inp.get('type')=='conditional':
  for case in inp.get('cases',[]):
   print(' case', case.get('value'))
   for ci in case.get('inputs',[]):
    print('  input', ci.get('name'), ci.get('type'), 'value', ci.get('value'))
    if ci.get('type')=='select' and ci.get('name')=='index':
     opts=ci.get('options',[])
     for o in opts:
      if o[1].startswith('hg'):
       print('   opt', o[:2])
PY"

